// 2. Output TypeScript dataset: src/data/highIntentKeywords.ts
const tsContent = `/**
 * TAMIZHTECH ROBOTICS — 500 HIGH-INTENT KEYWORDS INTELLIGENCE REPOSITORY
 * 
 * Auto-generated & verified database mapping 500 high-intent search queries
 * across 8 business verticals, regional Tamil Nadu & Coimbatore geographies,
 * and Pan-India commercial search demand.
 */

export interface HighIntentKeyword {
  id: number;
  keyword: string;
  category: string;
  subcategory: string;
  intent: string;
  targetRegion: string;
  recommendedUrl: string;
  priority: 'P0' | 'P1' | 'P2' | 'P3';
}

export const highIntentKeywords: HighIntentKeyword[] = ${JSON.stringify(rawKeywords.map(k => ({
  id: k.id,
  keyword: k.keyword,
  category: k.cat,
  subcategory: k.sub,
  intent: k.intent,
  targetRegion: k.region,
  recommendedUrl: k.url,
  priority: k.priority
})), null, 2)};

/**
 * Filter keywords by category
 */
export function getKeywordsByCategory(category: string): HighIntentKeyword[] {
  return highIntentKeywords.filter(k => k.category.toLowerCase().includes(category.toLowerCase()));
}

/**
 * Filter keywords by target URL destination
 */
export function getKeywordsByUrl(url: string): HighIntentKeyword[] {
  return highIntentKeywords.filter(k => k.recommendedUrl === url);
}

/**
 * Extract Category 8 AEO & GEO questions (IDs 466–500)
 */
export function getAeoNaturalQuestions(): HighIntentKeyword[] {
  return highIntentKeywords.filter(k => k.id >= 466 && k.id <= 500);
}

/**
 * Extract hyper-local Coimbatore & Tamil Nadu queries
 */
export function getLocalKeywords(region?: 'Coimbatore' | 'Tamil Nadu'): HighIntentKeyword[] {
  if (region === 'Coimbatore') {
    return highIntentKeywords.filter(k => k.targetRegion.toLowerCase().includes('coimbatore'));
  }
  if (region === 'Tamil Nadu') {
    return highIntentKeywords.filter(k => k.targetRegion.toLowerCase().includes('tamil nadu'));
  }
  return highIntentKeywords.filter(k => 
    k.targetRegion.toLowerCase().includes('coimbatore') || 
    k.targetRegion.toLowerCase().includes('tamil nadu')
  );
}
`;

fs.writeFileSync(path.join(__dirname, '../src/data/highIntentKeywords.ts'), tsContent, 'utf8');
