// Group by category and subcategory
const categories = {};
for (const k of rawKeywords) {
  if (!categories[k.cat]) categories[k.cat] = {};
  if (!categories[k.cat][k.sub]) categories[k.cat][k.sub] = [];
  categories[k.cat][k.sub].push(k);
}

for (const [catName, subcats] of Object.entries(categories)) {
  md += `## ${catName}\n\n`;
  for (const [subName, items] of Object.entries(subcats)) {
    md += `### ${subName} (Keywords ${items[0].id}–${items[items.length - 1].id})\n\n`;
    md += `| ID | Keyword | Search Intent | Target Region | Recommended URL | Priority |\n`;
    md += `|---|---|---|---|---|---|\n`;
    for (const item of items) {
      md += `| ${item.id} | \`${item.keyword}\` | ${item.intent} | ${item.region} | \`${item.url}\` | **${item.priority}** |\n`;
    }
    md += `\n`;
  }
}

fs.writeFileSync(path.join(__dirname, '../docs/HIGH_INTENT_500_KEYWORD_STRATEGY.md'), md, 'utf8');
